<?php $post = $editing ?: ['id'=>'','title'=>'','slug'=>'','excerpt'=>'','content'=>'','cover_image'=>'','cover_alt'=>'','author_name'=>'Emb Chronicles','is_featured'=>0,'status'=>'draft','published_at'=>'','seo_title'=>'','seo_description'=>'']; ?>
<header class="admin-page-header"><div><p class="text-sm text-muted">Articles and education</p><h1>Blog</h1></div><a class="button button-primary" href="<?= e(url('/admin/blog?new=1')) ?>">+ New post</a></header>
<div class="admin-split">
    <section class="admin-card"><div class="space-y-3"><?php foreach ($posts as $item): ?><a class="admin-list-card <?= (int) ($post['id'] ?: 0) === (int) $item['id'] ? 'is-active' : '' ?>" href="<?= e(url('/admin/blog?edit=' . $item['id'])) ?>"><?php if ($item['cover_image']): ?><img src="<?= e(media_url($item['cover_image'])) ?>" alt="" class="size-16 rounded-xl object-cover"><?php else: ?><span class="grid size-16 shrink-0 place-items-center rounded-xl bg-blush text-xs font-bold text-wine">Article</span><?php endif; ?><div class="min-w-0 flex-1"><p class="truncate font-semibold text-wine"><?= e($item['title']) ?></p><p class="mt-1 text-xs text-muted"><?= e($item['published_at'] ? format_date($item['published_at']) : 'Not scheduled') ?><?= $item['is_featured'] ? ' · Featured' : '' ?></p></div><span class="status status-<?= e($item['status']) ?>"><?= e($item['status']) ?></span></a><?php endforeach; ?><?php if (!$posts): ?><div class="empty-state">No blog posts yet.</div><?php endif; ?></div></section>
    <section class="admin-card">
        <div class="admin-card-header"><div><p class="text-xs font-bold uppercase tracking-[.12em] text-muted"><?= $post['id'] ? 'Edit article' : 'Create article' ?></p><h2 class="mt-1"><?= e($post['title'] ?: 'New blog post') ?></h2></div><?php if ($post['id'] && $post['status'] === 'published'): ?><a class="text-sm font-semibold text-wine" href="<?= e(url('/blog/' . $post['slug'])) ?>" target="_blank" rel="noopener">Preview ↗</a><?php endif; ?></div>
        <form method="post" enctype="multipart/form-data" action="<?= e(url('/admin/blog')) ?>" class="mt-6 space-y-7" data-unsaved-form>
            <?= csrf_field() ?><input type="hidden" name="id" value="<?= e($post['id']) ?>">
            <div class="form-grid"><div class="form-field md:col-span-2"><label>Title <span>*</span></label><input class="form-control" name="title" maxlength="255" value="<?= e($post['title']) ?>" required></div><div class="form-field"><label>Slug</label><input class="form-control" name="slug" maxlength="255" value="<?= e($post['slug']) ?>"></div><div class="form-field"><label>Author</label><input class="form-control" name="author_name" maxlength="190" value="<?= e($post['author_name']) ?>"></div><div class="form-field md:col-span-2"><label>Excerpt <span>*</span></label><textarea class="form-control min-h-24" name="excerpt" maxlength="500" required><?= e($post['excerpt']) ?></textarea></div></div>
            <div class="form-field"><label>Article content <span>*</span></label><div class="rich-toolbar" data-rich-toolbar><button type="button" data-tag="h2">Heading</button><button type="button" data-tag="strong">Bold</button><button type="button" data-tag="ul">List</button><button type="button" data-tag="p">Paragraph</button></div><textarea class="form-control min-h-80 font-mono text-sm" name="content" data-rich-text required><?= e($post['content']) ?></textarea></div>
            <fieldset class="admin-fieldset"><legend>Cover image</legend><?php if ($post['cover_image']): ?><img src="<?= e(media_url($post['cover_image'])) ?>" alt="" class="mb-4 aspect-video w-full rounded-xl object-cover"><?php endif; ?><div class="form-grid"><div class="form-field"><label>Upload image</label><input class="file-control" type="file" name="cover_image" accept="image/jpeg,image/png,image/webp"></div><div class="form-field"><label>Or image path / URL</label><input class="form-control" name="cover_url" maxlength="500" value="<?= e($post['cover_image']) ?>"></div><div class="form-field md:col-span-2"><label>Alt text</label><input class="form-control" name="cover_alt" maxlength="255" value="<?= e($post['cover_alt']) ?>"></div><?php if ($post['cover_image']): ?><label class="consent-row md:col-span-2"><input type="checkbox" name="remove_cover" value="1"><span>Remove cover image</span></label><?php endif; ?></div></fieldset>
            <fieldset class="admin-fieldset"><legend>Publishing and search</legend><div class="form-grid"><div class="form-field"><label>Status</label><select class="form-control" name="status"><option value="draft" <?= $post['status'] === 'draft' ? 'selected' : '' ?>>Draft</option><option value="published" <?= $post['status'] === 'published' ? 'selected' : '' ?>>Published</option></select></div><div class="form-field"><label>Publish date and time</label><input class="form-control" type="datetime-local" name="published_at" value="<?= e($post['published_at'] ? str_replace(' ', 'T', substr($post['published_at'], 0, 16)) : '') ?>"></div><div class="form-field"><label>SEO title</label><input class="form-control" name="seo_title" maxlength="255" value="<?= e($post['seo_title']) ?>"></div><div class="form-field"><label>SEO description</label><textarea class="form-control" name="seo_description" maxlength="320"><?= e($post['seo_description']) ?></textarea></div><label class="consent-row md:col-span-2"><input type="checkbox" name="is_featured" value="1" <?= $post['is_featured'] ? 'checked' : '' ?>><span>Feature this article first on the blog page</span></label></div></fieldset>
            <div class="admin-savebar"><button class="button button-primary" name="action" value="save">Save post</button><?php if ($post['id']): ?><button class="button button-danger ml-auto" name="action" value="delete" data-confirm="Delete this blog post?">Delete</button><?php endif; ?></div>
        </form>
    </section>
</div>
